// Validates and normalizes the incoming assessment payload.
// Every downstream node reads its inputs from here, so payload shape changes
// only ever need to be handled in this one node.

const CONFIG = {
  model: 'gpt-4.1',
  temperature_analysis: 0.1, // Agents 1 & 2: analysis must be reproducible run-to-run.
  temperature_writing: 0.4, // Agent 3: enough freedom for natural prose, not enough to drift.
  max_tokens: 4000, // NOTE: if you switch to a reasoning model, rename this to max_completion_tokens.
};

const raw = $input.first().json;
const payload = raw.body && typeof raw.body === 'object' ? raw.body : raw;

const num = (v) => {
  const n = Number(v);
  return Number.isFinite(n) ? n : null;
};

// Accepts either [{ dimension, score }] or { "Dimension Name": 72 }.
function normalizeScores(input) {
  if (!input) return [];
  const rows = Array.isArray(input)
    ? input
    : Object.entries(input).map(([dimension, score]) => ({ dimension, score }));
  return rows
    .map((r) => ({
      dimension: String(r.dimension ?? r.name ?? '').trim(),
      score: num(r.score ?? r.value),
      max_score: num(r.max_score) ?? 100,
    }))
    .filter((r) => r.dimension && r.score !== null);
}

function normalizeBenchmarks(input) {
  if (!input) return [];
  const rows = Array.isArray(input)
    ? input
    : Object.entries(input).map(([dimension, benchmark_score]) => ({ dimension, benchmark_score }));
  return rows
    .map((r) => ({
      dimension: String(r.dimension ?? r.name ?? '').trim(),
      benchmark_score: num(r.benchmark_score ?? r.benchmark ?? r.score ?? r.value),
    }))
    .filter((r) => r.dimension && r.benchmark_score !== null);
}

const assessment_type = String(payload.assessment_type ?? '').trim();
if (!assessment_type) {
  throw new Error('assessment_type is required.');
}

const scores = normalizeScores(payload.scored_results ?? payload.scores);
if (scores.length === 0) {
  throw new Error('scored_results is required and must contain at least one scored dimension.');
}

const benchmarks = normalizeBenchmarks(payload.benchmark_data ?? payload.benchmarks);

// Partial or absent benchmarks are allowed - the prompts handle them explicitly
// rather than letting the model invent a comparison figure.
const benchmarked = new Set(benchmarks.map((b) => b.dimension.toLowerCase()));
const missing_benchmarks = scores
  .map((s) => s.dimension)
  .filter((d) => !benchmarked.has(d.toLowerCase()));

return [
  {
    json: {
      config: CONFIG,
      assessment_type,
      recipient_name: String(payload.recipient_name ?? payload.company_name ?? 'the respondent').trim(),
      benchmark_label: String(payload.benchmark_label ?? 'peer benchmark').trim(),
      scores,
      benchmarks,
      missing_benchmarks,
      raw_answers: Array.isArray(payload.raw_answers) ? payload.raw_answers : [],
    },
  },
];

// Agent 1 - Insight Extraction. Builds the full OpenAI request body so the
// HTTP node stays a dumb transport and the prompt stays readable/diffable here.

const input = $input.first().json;

const system = [
  'You are a senior organizational psychologist and data analyst specializing in ' +
    input.assessment_type +
    ' assessments. Your job is to extract accurate, evidence-based insights from a completed assessment - nothing more.',
  '',
  'You will be given:',
  "1. The respondent's scored results, broken down by dimension.",
  '2. Benchmark data for those dimensions, where it exists.',
  '3. Any raw qualitative answers relevant to interpretation.',
  '',
  'RULES:',
  '- Every claim you make MUST be traceable to a specific score, score gap, or answer pattern. Never state a strength, weakness, or flag without citing the exact dimension and the number behind it.',
  '- Do not soften or inflate findings to sound positive. Be accurate, not flattering.',
  '- Do not generate recommendations or advice in this step - that happens later in the chain.',
  '- Flag anything unusual: contradictory answers, extreme outliers, or patterns that do not fit a coherent profile. These often matter more than clean results.',
  '- For each dimension that HAS a benchmark, state the direction and size of the gap numerically (e.g. "14 points below peer benchmark", not "somewhat below average").',
  '- For each dimension with NO benchmark supplied, set direction to "no benchmark available", set benchmark_score and gap to null, and make no claim about how it compares. Never estimate, infer, or invent a benchmark value.',
  '- Use only the numbers supplied in the input. Do not compute percentiles or norms that were not given to you.',
  '- Write for a business audience: precise, confident, zero filler. Avoid generic phrasing such as "it is important to note that" or "overall, the results suggest".',
].join('\n');

// dimensions_without_benchmark is passed explicitly so the model cannot quietly
// fill the gap from prior knowledge.
const userPayload = {
  assessment_type: input.assessment_type,
  benchmark_label: input.benchmark_label,
  scored_results: input.scores,
  benchmark_data: input.benchmarks,
  dimensions_without_benchmark: input.missing_benchmarks,
  raw_answers: input.raw_answers,
};

const finding = {
  type: 'object',
  properties: {
    area: { type: 'string' },
    evidence: { type: 'string' },
    score_reference: { type: 'string' },
  },
  required: ['area', 'evidence', 'score_reference'],
  additionalProperties: false,
};

const schema = {
  type: 'object',
  properties: {
    strengths: { type: 'array', items: finding },
    weaknesses: { type: 'array', items: finding },
    green_flags: {
      type: 'array',
      items: {
        type: 'object',
        properties: { observation: { type: 'string' }, evidence: { type: 'string' } },
        required: ['observation', 'evidence'],
        additionalProperties: false,
      },
    },
    red_flags: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          observation: { type: 'string' },
          evidence: { type: 'string' },
          severity: { type: 'string', enum: ['low', 'medium', 'high'] },
        },
        required: ['observation', 'evidence', 'severity'],
        additionalProperties: false,
      },
    },
    patterns: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          description: { type: 'string' },
          dimensions_involved: { type: 'array', items: { type: 'string' } },
          evidence: { type: 'string' },
        },
        required: ['description', 'dimensions_involved', 'evidence'],
        additionalProperties: false,
      },
    },
    benchmark_differences: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          dimension: { type: 'string' },
          respondent_score: { type: 'number' },
          benchmark_score: { type: ['number', 'null'] },
          gap: { type: ['number', 'null'] },
          direction: {
            type: 'string',
            enum: ['above', 'below', 'at benchmark', 'no benchmark available'],
          },
        },
        required: ['dimension', 'respondent_score', 'benchmark_score', 'gap', 'direction'],
        additionalProperties: false,
      },
    },
  },
  required: [
    'strengths',
    'weaknesses',
    'green_flags',
    'red_flags',
    'patterns',
    'benchmark_differences',
  ],
  additionalProperties: false,
};

return [
  {
    json: {
      request_body: {
        model: input.config.model,
        temperature: input.config.temperature_analysis,
        max_tokens: input.config.max_tokens,
        messages: [
          { role: 'system', content: system },
          { role: 'user', content: JSON.stringify(userPayload, null, 2) },
        ],
        response_format: {
          type: 'json_schema',
          json_schema: { name: 'assessment_insights', strict: true, schema },
        },
      },
    },
  },
];

// Parses Agent 1's response and enforces the "no invented benchmarks" rule in
// code, so a prompt slip cannot put a fabricated comparison into the report.

const res = $input.first().json;
const choice = res.choices && res.choices[0];

if (!choice) {
  throw new Error('Agent 1: no choice returned. Raw response: ' + JSON.stringify(res).slice(0, 500));
}
if (choice.message && choice.message.refusal) {
  throw new Error('Agent 1 refused to answer: ' + choice.message.refusal);
}
if (choice.finish_reason === 'length') {
  throw new Error('Agent 1: output truncated (finish_reason=length). Increase config.max_tokens.');
}

let insights;
try {
  insights = JSON.parse(choice.message.content);
} catch (e) {
  throw new Error('Agent 1 returned invalid JSON: ' + e.message);
}

const prep = $('Prepare Input').first().json;
const supplied = new Map(prep.benchmarks.map((b) => [b.dimension.toLowerCase(), b.benchmark_score]));
const actual = new Map(prep.scores.map((s) => [s.dimension.toLowerCase(), s.score]));

insights.benchmark_differences = (insights.benchmark_differences || []).map((d) => {
  const key = String(d.dimension || '').toLowerCase();
  const trueScore = actual.has(key) ? actual.get(key) : d.respondent_score;

  if (!supplied.has(key)) {
    return {
      ...d,
      respondent_score: trueScore,
      benchmark_score: null,
      gap: null,
      direction: 'no benchmark available',
    };
  }

  // Recompute the gap from source data rather than trusting the model's arithmetic.
  const bench = supplied.get(key);
  const gap = Math.round((trueScore - bench) * 100) / 100;
  return {
    ...d,
    respondent_score: trueScore,
    benchmark_score: bench,
    gap,
    direction: gap > 0 ? 'above' : gap < 0 ? 'below' : 'at benchmark',
  };
});

return [{ json: { insights, usage: res.usage || null } }];

// Agent 2 - Recommendation & Strategy. Consumes only Agent 1's structured
// findings, so every recommendation is anchored to a cited finding.

const prep = $('Prepare Input').first().json;
const insights = $input.first().json.insights;

const system = [
  'You are a strategy consultant who advises organizations based on ' +
    prep.assessment_type +
    ' assessment results. You will be given a structured set of findings (strengths, weaknesses, flags, patterns, benchmark gaps) already extracted from the assessment. Convert those findings into recommendations a real consultant would give in a paid session - not generic self-help advice.',
  '',
  'RULES:',
  '- Every recommendation must name the specific finding it responds to, quoting the dimension and figure from that finding in responds_to_finding.',
  '- Never give advice that could apply to almost anyone regardless of their results. "Communicate more effectively" or "invest in training" are banned unless tied to a specific cited weakness with a concrete mechanism.',
  '- Prioritize: assign priority "high" to recommendations addressing the largest benchmark gaps or highest-severity red flags, and order the array so high-priority items come first.',
  '- Do not recommend anything against a dimension marked "no benchmark available" on the basis of a comparison. You may still act on the raw score.',
  '- Keep the three output types genuinely distinct:',
  '  1. practical_recommendations - immediate, tactical, low-effort actions that can start this quarter.',
  '  2. innovative_strategies - non-obvious moves grounded in how top performers in this benchmark group actually operate.',
  '  3. strategic_initiatives - larger, longer-term structural moves suited to leadership or board-level decision-making.',
  '- Language must be decisive and specific. No hedging ("could potentially consider"), no filler.',
].join('\n');

const schema = {
  type: 'object',
  properties: {
    practical_recommendations: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          recommendation: { type: 'string' },
          responds_to_finding: { type: 'string' },
          effort: { type: 'string', enum: ['low', 'medium', 'high'] },
          priority: { type: 'string', enum: ['low', 'medium', 'high'] },
        },
        required: ['recommendation', 'responds_to_finding', 'effort', 'priority'],
        additionalProperties: false,
      },
    },
    innovative_strategies: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          strategy: { type: 'string' },
          rationale: { type: 'string' },
          responds_to_finding: { type: 'string' },
        },
        required: ['strategy', 'rationale', 'responds_to_finding'],
        additionalProperties: false,
      },
    },
    strategic_initiatives: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          initiative: { type: 'string' },
          responds_to_finding: { type: 'string' },
          impact: { type: 'string', enum: ['low', 'medium', 'high'] },
          timeframe: { type: 'string', enum: ['short-term', 'medium-term', 'long-term'] },
        },
        required: ['initiative', 'responds_to_finding', 'impact', 'timeframe'],
        additionalProperties: false,
      },
    },
  },
  required: ['practical_recommendations', 'innovative_strategies', 'strategic_initiatives'],
  additionalProperties: false,
};

return [
  {
    json: {
      request_body: {
        model: prep.config.model,
        temperature: prep.config.temperature_analysis,
        max_tokens: prep.config.max_tokens,
        messages: [
          { role: 'system', content: system },
          { role: 'user', content: JSON.stringify({ findings: insights }, null, 2) },
        ],
        response_format: {
          type: 'json_schema',
          json_schema: { name: 'assessment_recommendations', strict: true, schema },
        },
      },
    },
  },
];

const res = $input.first().json;
const choice = res.choices && res.choices[0];

if (!choice) {
  throw new Error('Agent 2: no choice returned. Raw response: ' + JSON.stringify(res).slice(0, 500));
}
if (choice.message && choice.message.refusal) {
  throw new Error('Agent 2 refused to answer: ' + choice.message.refusal);
}
if (choice.finish_reason === 'length') {
  throw new Error('Agent 2: output truncated (finish_reason=length). Increase config.max_tokens.');
}

let recommendations;
try {
  recommendations = JSON.parse(choice.message.content);
} catch (e) {
  throw new Error('Agent 2 returned invalid JSON: ' + e.message);
}

return [{ json: { recommendations, usage: res.usage || null } }];

// Builds dashboard_data deterministically from the original scores and from
// Agent 2's priorities. No model involved: the charts can never disagree with
// the source data, and no number is ever re-typed by an LLM.

const prep = $('Prepare Input').first().json;
const insights = $('Parse Agent 1').first().json.insights;
const recommendations = $input.first().json.recommendations;

const benchMap = new Map(prep.benchmarks.map((b) => [b.dimension.toLowerCase(), b.benchmark_score]));
const round2 = (n) => Math.round(n * 100) / 100;

const dimension_scores = prep.scores.map((s) => {
  const key = s.dimension.toLowerCase();
  const benchmark_score = benchMap.has(key) ? benchMap.get(key) : null;
  return {
    dimension: s.dimension,
    respondent_score: s.score,
    benchmark_score,
    max_score: s.max_score,
    gap: benchmark_score === null ? null : round2(s.score - benchmark_score),
  };
});

const strengths_vs_weaknesses = {
  strengths_count: (insights.strengths || []).length,
  weaknesses_count: (insights.weaknesses || []).length,
  green_flags_count: (insights.green_flags || []).length,
  red_flags_count: (insights.red_flags || []).length,
};

const rank = { high: 0, medium: 1, low: 2 };
const priority_actions = (recommendations.practical_recommendations || [])
  .slice()
  .sort((a, b) => (rank[a.priority] ?? 3) - (rank[b.priority] ?? 3))
  .map((r) => ({
    action: r.recommendation,
    priority: r.priority,
    effort: r.effort,
    responds_to_finding: r.responds_to_finding,
  }));

const benchmarked = dimension_scores.filter((d) => d.benchmark_score !== null);
const below = benchmarked.filter((d) => d.gap < 0);

const summary = {
  dimensions_assessed: dimension_scores.length,
  dimensions_benchmarked: benchmarked.length,
  dimensions_above_benchmark: benchmarked.filter((d) => d.gap > 0).length,
  dimensions_below_benchmark: below.length,
  // Null when nothing sits below benchmark, rather than reporting the least-above dimension.
  largest_gap_below: below.length ? below.reduce((a, b) => (a.gap <= b.gap ? a : b)) : null,
  // Normalized so dimensions scored out of different maximums average fairly.
  average_score_pct: round2(
    (dimension_scores.reduce((sum, d) => sum + d.respondent_score / d.max_score, 0) /
      dimension_scores.length) *
      100,
  ),
};

return [
  {
    json: {
      recommendations,
      dashboard_data: {
        dimension_scores,
        strengths_vs_weaknesses,
        priority_actions,
        summary,
      },
    },
  },
];

// Agent 3 - Report Writer. Narrative only. dashboard_data was already computed
// in code, and is passed in read-only so the prose quotes the same figures the
// charts render.

const prep = $('Prepare Input').first().json;
const insights = $('Parse Agent 1').first().json.insights;
const staged = $input.first().json;

const system = [
  'You are producing the final written deliverable of a professional ' +
    prep.assessment_type +
    ' assessment report for ' +
    prep.recipient_name +
    '. You will receive extracted insights (from an analysis step), recommendations (from a strategy step), and the exact computed figures used by the report dashboard.',
  '',
  'RULES:',
  '- Write in a confident, consultative tone - the way a senior consultant presents findings to executives. No robotic AI tone, no boilerplate phrases, no hedging.',
  '- The executive_summary must be 3-5 sentences and must stand alone. It is what a board member reads if they read nothing else.',
  '- Every section must be specific to THIS respondent. If a sentence would still be true for a different respondent with different scores, rewrite it.',
  '- Quote figures only from the supplied data, and quote them exactly as given in dashboard_figures. Do not round, restate, or recompute them.',
  '- Never describe a dimension as above or below benchmark when its benchmark_score is null. Refer to those dimensions by their raw score only.',
  '- Do not output any numbers-only structures, tables, or JSON inside the narrative fields - the dashboard is rendered separately. Prose only.',
  '- Each narrative field is plain prose (paragraphs). You may use short line breaks between paragraphs but no markdown headings.',
].join('\n');

const userPayload = {
  recipient_name: prep.recipient_name,
  assessment_type: prep.assessment_type,
  benchmark_label: prep.benchmark_label,
  insights,
  recommendations: staged.recommendations,
  dashboard_figures: staged.dashboard_data,
};

const schema = {
  type: 'object',
  properties: {
    executive_summary: { type: 'string' },
    key_strengths: { type: 'string' },
    areas_for_improvement: { type: 'string' },
    flags_summary: { type: 'string' },
    benchmark_comparison_narrative: { type: 'string' },
    recommendations_narrative: { type: 'string' },
    strategic_initiatives_narrative: { type: 'string' },
  },
  required: [
    'executive_summary',
    'key_strengths',
    'areas_for_improvement',
    'flags_summary',
    'benchmark_comparison_narrative',
    'recommendations_narrative',
    'strategic_initiatives_narrative',
  ],
  additionalProperties: false,
};

return [
  {
    json: {
      request_body: {
        model: prep.config.model,
        temperature: prep.config.temperature_writing,
        max_tokens: prep.config.max_tokens,
        messages: [
          { role: 'system', content: system },
          { role: 'user', content: JSON.stringify(userPayload, null, 2) },
        ],
        response_format: {
          type: 'json_schema',
          json_schema: { name: 'assessment_report_narrative', strict: true, schema },
        },
      },
    },
  },
];

// Merges the narrative with the code-computed dashboard block and returns the
// final report payload the frontend consumes.

const res = $input.first().json;
const choice = res.choices && res.choices[0];

if (!choice) {
  throw new Error('Agent 3: no choice returned. Raw response: ' + JSON.stringify(res).slice(0, 500));
}
if (choice.message && choice.message.refusal) {
  throw new Error('Agent 3 refused to answer: ' + choice.message.refusal);
}
if (choice.finish_reason === 'length') {
  throw new Error('Agent 3: output truncated (finish_reason=length). Increase config.max_tokens.');
}

let report_narrative;
try {
  report_narrative = JSON.parse(choice.message.content);
} catch (e) {
  throw new Error('Agent 3 returned invalid JSON: ' + e.message);
}

const prep = $('Prepare Input').first().json;
const insights = $('Parse Agent 1').first().json.insights;
const staged = $('Build Dashboard Data').first().json;

const usage = [
  $('Parse Agent 1').first().json.usage,
  $('Parse Agent 2').first().json.usage,
  res.usage || null,
].filter(Boolean);

const total_tokens = usage.reduce((sum, u) => sum + (u.total_tokens || 0), 0);

return [
  {
    json: {
      meta: {
        assessment_type: prep.assessment_type,
        recipient_name: prep.recipient_name,
        benchmark_label: prep.benchmark_label,
        generated_at: new Date().toISOString(),
        model: prep.config.model,
        dimensions_without_benchmark: prep.missing_benchmarks,
        total_tokens,
      },
      report_narrative,
      dashboard_data: staged.dashboard_data,
      // Kept for auditability: lets you trace any sentence in the report back to
      // the finding and recommendation it came from.
      source_findings: {
        insights,
        recommendations: staged.recommendations,
      },
    },
  },
];
